104	package net.officefloor.hq.app.pool;
105	
106	import java.math.BigDecimal;
107	import java.time.LocalDate;
108	import java.time.format.DateTimeParseException;
109	import java.util.regex.Pattern;
110	import net.officefloor.hq.app.person.Person;
111	import net.officefloor.hq.app.person.PersonRepository;
112	import net.officefloor.plugin.variable.Out;
113	import org.springframework.web.bind.annotation.PathVariable;
114	import org.springframework.web.bind.annotation.RequestBody;
115	import org.springframework.web.bind.annotation.RequestParam;
116	
117	/** Adds a person of the sheet, or another pool of the sheet, to the pool with a share percent (at most two
118	 *  decimals, more than 0.00 and at most 100.00): refused (nothing written) for no such pool or person, a
119	 *  person already in the pool, or a bad share; and for a pool that is already a member of a pool, that
120	 *  would contain itself through any chain, or that would make a chain of pools more than three deep. The
121	 *  membership may run from and/or to a date (optional); refused for a date that is not one, or a to-date
122	 *  before the from-date. */
123	public class AddPoolMember {
124	
125	    private static final Pattern SHARE = Pattern.compile("\\d+(\\.\\d{1,2})?");
126	
127	    private static final BigDecimal MAX = new BigDecimal("100.00");
128	
129	    /** The most pools in a chain, the one a member of none counting as the first. */
130	    private static final int MAX_DEPTH = 3;
131	
132	    public void add(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") long poolId,
133	            @RequestParam(name = "by", required = false) String by, @RequestBody PoolMemberRequest request,
134	            PoolRepository pools, PersonRepository people, Out<PoolMemberAdded> added)
135	            throws InvalidPoolException {
136	        String id = sheetId.trim();
137	        String pool = pools.nameOf(id, poolId);
138	        if (pool == null) {
139	            throw new InvalidPoolException("No such pool: " + poolId);
140	        }
141	        if (request == null || (request.personId() == null && request.memberPoolId() == null)) {
142	            throw new InvalidPoolException("No member named");
143	        }
144	        Person person = null;
145	        String memberPool = null;
146	        if (request.personId() != null) {
147	            person = people.find(id, request.personId());
148	            if (person == null) {
149	                throw new InvalidPoolException("No such person on the sheet: " + request.personId());
150	            }
151	        } else {
152	            memberPool = pools.nameOf(id, request.memberPoolId());
153	            if (memberPool == null) {
154	                throw new InvalidPoolException("No such pool on the sheet: " + request.memberPoolId());
155	            }
156	        }
157	        String text = request.share() == null ? "" : request.share().trim();
158	        if (!SHARE.matcher(text).matches()) {
159	            throw new InvalidPoolException("A share is a percent with at most two decimals");
160	        }
161	        BigDecimal share = new BigDecimal(text).setScale(2);
162	        if (share.signum() <= 0 || share.compareTo(MAX) > 0) {
163	            throw new InvalidPoolException("A share is more than 0.00 and at most 100.00");
164	        }
165	        String from = date(request.from());
166	        String to = date(request.to());
167	        if (from != null && to != null && to.compareTo(from) < 0) {
168	            throw new InvalidPoolException("The membership ends before it starts: " + from + " to " + to);
169	        }
170	        String user = by == null ? "" : by;
171	        if (person != null) {
172	            if (pools.hasMember(poolId, person.getId())) {
173	                throw new InvalidPoolException(person.getName() + " is already in " + pool);
174	            }
175	            pools.addMember(id, poolId, person.getId(), share, from, to, user);
176	            added.set(new PoolMemberAdded(id, pool, person.getName(), share.toPlainString(), from, to, user));
177	            return;
178	        }
179	        long child = request.memberPoolId();
180	        int level = 0;
181	        for (Long above = poolId; above != null && level <= MAX_DEPTH; above = pools.parentOf(above)) {
182	            if (above == child) {
183	                throw new InvalidPoolException(memberPool + " cannot contain itself");
184	            }
185	            level++;
186	        }
187	        if (pools.parentOf(child) != null) {
188	            throw new InvalidPoolException(memberPool + " is already a member of a pool");
189	        }
190	        if (level + height(pools, child, 1) > MAX_DEPTH) {
191	            throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep");
192	        }
193	        pools.addPoolMember(id, poolId, child, share, from, to, user);
194	        added.set(new PoolMemberAdded(id, pool, memberPool, share.toPlainString(), from, to, user));
195	    }
196	
197	    /** The date as yyyy-mm-dd, or null when blank. */
198	    private static String date(String text) throws InvalidPoolException {
199	        String value = text == null ? "" : text.trim();
200	        if (value.isEmpty()) {
201	            return null;
202	        }
203	        try {
204	            return LocalDate.parse(value).toString();
205	        } catch (DateTimeParseException e) {
206	            throw new InvalidPoolException("Not a date: " + value);
207	        }
208	    }
209	
210	    /** The most pools in a chain down from {@code poolId}, itself counting as one (stops past the limit). */
211	    private static int height(PoolRepository pools, long poolId, int depth) {
212	        int most = 1;
213	        if (depth > MAX_DEPTH) return most;
214	        for (long below : pools.childrenOf(poolId)) {
215	            most = Math.max(most, 1 + height(pools, below, depth + 1));
216	        }
217	        return most;
218	    }
219	}
