375	        Map<Long, BigDecimal> totals = new HashMap<>();
376	        for (Map.Entry<Long, List<PoolMember>> pool : members.entrySet()) {
377	            BigDecimal total = BigDecimal.ZERO.setScale(2);
378	            for (PoolMember m : pool.getValue()) {
379	                if (m.current()) total = total.add(new BigDecimal(m.share()));
380	            }
381	            totals.put(pool.getKey(), total);
382	        }
383	        Map<Long, List<PoolMember>> cut = new HashMap<>();
384	        for (Long id : names.keySet()) cutOf(id, members, parents, totals, held, pot, cut, new HashSet<>());
385	        List<Pool> pools = new ArrayList<>();
386	        for (Map.Entry<Long, String> pool : names.entrySet()) {
387	            BigDecimal total = totals.get(pool.getKey());
388	            pools.add(new Pool(pool.getKey(), sheetId, pool.getValue(), cut.get(pool.getKey()),
389	                    total.toPlainString(), total.compareTo(FULL) == 0, parents.get(pool.getKey()), false));
390	        }
391	        pools.addAll(crewPools(sheetId, pot, held));
392	        return pools;
393	    }
394	
395	    /** The sheet's crews in the order they were added, each as a pool under its name (id: the crew's id
396	     *  negated; a member of no pool, and taking none): the lead then the members in the order added, at
397	     *  equal shares of 100.00 as a person's patrons' shares are (the remainder on the lead), cutting the
398	     *  sheet's pot like any pool. A crew without a lead (they left the sheet) is its members alone; with
399	     *  none either, it has no members and a total of 0.00. */
400	    private List<Pool> crewPools(String sheetId, BigDecimal pot, Set<Long> held) {
401	        Set<Long> retired = new HashSet<>(jdbc.queryForList(
402	                "SELECT id FROM person WHERE sheet_id = ? AND retired_from IS NOT NULL", Long.class, sheetId));
403	        List<Pool> pools = new ArrayList<>();
404	        for (Crew crew : crews.list(sheetId)) {
405	            List<Long> ids = new ArrayList<>();
406	            List<String> names = new ArrayList<>();
407	            if (crew.leadId() != null) {
408	                ids.add(crew.leadId());
409	                names.add(crew.lead());
410	            }
411	            for (CrewMember m : crew.members()) {
412	                ids.add(m.personId());
413	                names.add(m.name());
414	            }
415	            long hundredths = FULL.movePointRight(2).longValueExact();
416	            if (ids.isEmpty()) {
417	                pools.add(new Pool(-crew.id(), sheetId, crew.name(), List.of(), "0.00", false, null, true));
418	                continue;
419	            }
420	            long each = hundredths / ids.size();
421	            List<PoolMember> members = new ArrayList<>();
422	            for (int i = 0; i < ids.size(); i++) {
423	                long share = i == 0 ? hundredths - each * (ids.size() - 1) : each;
424	                members.add(new PoolMember(ids.get(i), null, names.get(i),
425	                        BigDecimal.valueOf(share, 2).toPlainString(), retired.contains(ids.get(i)), null, null, true, ""));
426	            }
427	            pools.add(new Pool(-crew.id(), sheetId, crew.name(), pot != null ? cut(members, pot, held) : members,
428	                    FULL.toPlainString(), true, null, true));
429	        }
430	        return pools;
431	    }
432	
433	    /** The pool's members with their cuts, worked out (and kept in {@code cut}) after those of the pool above
434	     *  it: its pot is the sheet's pot when it is a member of none, else its cut in the pool above. */
435	    private static List<PoolMember> cutOf(Long id, Map<Long, List<PoolMember>> members, Map<Long, Long> parents,
436	            Map<Long, BigDecimal> totals, Set<Long> held, BigDecimal sheetPot, Map<Long, List<PoolMember>> cut, Set<Long> seen) {
437	        List<PoolMember> done = cut.get(id);
438	        if (done != null) return done;
439	        List<PoolMember> of = members.get(id);
440	        BigDecimal pot = null;
441	        Long parent = parents.get(id);
442	        if (parent == null) {
443	            pot = sheetPot;
444	        } else if (seen.add(id) && members.containsKey(parent)) {
445	            for (PoolMember m : cutOf(parent, members, parents, totals, held, sheetPot, cut, seen)) {
446	                if (id.equals(m.poolId()) && !m.cut().isEmpty()) pot = new BigDecimal(m.cut());
447	            }
448	        }
449	        List<PoolMember> result = pot != null && totals.get(id).compareTo(FULL) == 0 ? cut(of, pot, held) : of;
450	        cut.put(id, result);
451	        return result;
452	    }
453	
454	    /** The members with their cuts of the pot. A member with a cut is one neither retired nor on a hold in
455	     *  force on the sheet's today ({@code held}); the others' cut is 0.00, but a member whose dates do not
456	     *  include the sheet's today is left out entirely (cut ""), as is every member when each current member
457	     *  is retired (the pool shows no cuts). Each member with a cut gets the pot
458	     *  times their share over the shares of the members with a cut added up, rounded half to even to two
459	     *  decimals; the remainder goes to the member with the smallest non-zero cut (the latest added on a tie; a
460	     *  member with no cut gets none), or to the last member with a cut and a share when no cut is non-zero, so the cuts total exactly the pot (all 0.00 when no member has a cut). */
461	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
462	        if (members.stream().anyMatch(PoolMember::current)
463	                && members.stream().filter(PoolMember::current).allMatch(PoolMember::retired)) {
464	            return members.stream().map(m -> m.withCut("")).toList();
465	        }
466	        BigDecimal[] cuts = new BigDecimal[members.size()];
467	        boolean[] cutting = new boolean[members.size()];
468	        BigDecimal shares = BigDecimal.ZERO.setScale(2);
469	        for (int i = 0; i < members.size(); i++) {
470	            PoolMember m = members.get(i);
471	            cutting[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
472	            if (cutting[i]) shares = shares.add(new BigDecimal(m.share()));
473	        }
474	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
475	        int smallest = -1;
476	        int last = -1;
477	        for (int i = 0; i < members.size(); i++) {
478	            BigDecimal share = new BigDecimal(members.get(i).share());
479	            cuts[i] = cutting[i] ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
480	                    : BigDecimal.ZERO.setScale(2);
481	            sum = sum.add(cuts[i]);
482	            if (cutting[i] && share.signum() != 0) last = i;
483	            if (cutting[i] && cuts[i].signum() != 0
484	                    && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
485	                smallest = i;
486	            }
487	        }
488	        int to = smallest >= 0 ? smallest : last;
489	        if (to >= 0) cuts[to] = cuts[to].add(pot.subtract(sum));
490	        List<PoolMember> cut = new ArrayList<>();
491	        for (int i = 0; i < members.size(); i++) {
492	            cut.add(members.get(i).withCut(members.get(i).current() ? cuts[i].toPlainString() : ""));
493	        }
494	        return cut;
495	    }
