test("cut history scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = ui.userPage(browser, "uma", sheet);
  ui.setToday(pg_uma, "2026-03-10");
  ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  ui.setSetting(pg_uma, "late-pct", "10.00");
  ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  ui.setSetting(pg_uma, "terms-C", "3");
  ui.setSetting(pg_uma, "proof-threshold", "1.00");
  ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  ui.addVoidReason(pg_uma, "error")).toBe(true);
  ui.setSetting(pg_uma, "pot", "7.77");
  ui.setSetting(pg_uma, "alert-threshold", "3.00");
