  test("cut history scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "7");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "cap", "2.00");
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "note-threshold", "1.00");
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.04", "note": ""})).toBe(true);
    await ui.setSetting(pg_uma, "pot", "33.33");
    await ui.setSetting(pg_uma, "fiscal-start-month", "4");
    await ui.setSetting(pg_uma, "alert-threshold", "3.00");
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
    await ui.setSetting(pg_uma, "review-threshold", "4.00");
    await ui.setSetting(pg_uma, "escalate-after", "7");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-03-01"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
    expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "3"}));
    expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
    expect(await ui.editPerson(pg_uma, p_ada, {"terms": "3", "termsFrom": "2026-03-12"})).toBe(true);
    expect(await ui.addAlias(pg_uma, p_ben, "Al")).toBe(true);
    await ui.expectAuditView(pg_uma, "Ada", [
      `PERSON_EDITED sheet=${sheet} by=uma name=Ada grade=C terms=3`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=C`
    ]);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.retire(pg_wes, p_cam, "2026-03-09")).toBe(false);
    await ui.showRetired(pg_wes, true);
    expect(await ui.addClaim(pg_wes, p_ada, {"amount": "25.00", "date": "2026-04-02"})).toBeNull();
    expect(await ui.inlineGrade(pg_wes, p_ben, "A")).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    await ui.refresh(pg_vic);
    const c_ben_0 = ui.must(await ui.claimFromTemplate(pg_vic, p_ben, "T1"));
    await ui.refresh(pg_vic);
    expect(await ui.bulkReassign(pg_vic, [c_ben_0], "Ben")).toEqual({ reassigned: 1, refused: 0 });
    expect(await ui.statement(pg_vic, p_cam)).toBe(true);
    expect(await ui.editPerson(pg_vic, p_cam, {"grade": "A"})).toBe(true);
    expect(await ui.bulkGrade(pg_vic, [p_cam, p_ada], {"grade": "C", "from": "2026-03-28"})).toBe(2);
    await ui.refresh(pg_vic);
    expect(await ui.flag(pg_vic, p_cam, "check", "2026-04-30", "check")).toBe(true);
    expect(await ui.editPerson(pg_vic, p_ben, {"grade": "B"})).toBe(true);
    await ui.refresh(pg_vic);
    await ui.refresh(pg_uma);
    expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(false);
    expect(await ui.addAlias(pg_uma, p_ben, "")).toBe(false);
    expect(await ui.editInline(pg_uma, c_ben_0, "0.04")).toBe(true);
    expect(await ui.setSettingDated(pg_uma, "cap", "5.00", "2026-03-05", "2.00")).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.unstate(pg_vic, p_cam)).toBe(true);
    await ui.refresh(pg_vic);

