-- A hold is dated: it runs from its from-date to its to-date (none: open-ended), and a person may
-- have several over time. Only a person's OPEN claims dated within a hold count in no live total;
-- a claim bound by a statement still counts whatever its date. A person held before holds were
-- dated keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    from_date DATE         NOT NULL,
    to_date   DATE,
    held_by   VARCHAR(200) NOT NULL,
    held_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_hold_person ON person_hold (sheet_id, person_id, id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by)
    SELECT sheet_id, id, DATE '0001-01-01', NULL, created_by FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- The sheet's pools: a name (trimmed, unique on the sheet) and its members.
CREATE TABLE pool (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200)  NOT NULL,
    added_by  VARCHAR(200)  NOT NULL,
    CONSTRAINT pool_unique UNIQUE (sheet_id, name)
);
-- A pool's members: a person of the sheet (at most once in a pool) and their share percent. A retired
-- member's share counts as 0.00 toward the pool's total.
CREATE TABLE pool_member (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    pool_id   BIGINT        NOT NULL REFERENCES pool (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5,2)  NOT NULL,
    added_by  VARCHAR(200)  NOT NULL,
    CONSTRAINT pool_member_unique UNIQUE (pool_id, person_id)
);
-- The sheet's crews: a name (trimmed, unique on the sheet) and a lead, a person of the sheet.
CREATE TABLE crew (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200)  NOT NULL,
    lead_id   BIGINT        NOT NULL REFERENCES person (id),
    added_by  VARCHAR(200)  NOT NULL,
    CONSTRAINT crew_unique UNIQUE (sheet_id, name)
);
-- A crew's members: people of the sheet, each at most once in a crew and never its lead.
CREATE TABLE crew_member (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    crew_id   BIGINT        NOT NULL REFERENCES crew (id),
    person_id BIGINT        NOT NULL REFERENCES person (id),
    added_by  VARCHAR(200)  NOT NULL,
    CONSTRAINT crew_member_unique UNIQUE (crew_id, person_id)
);
